    'capture.loss': { t: (m) => `${kb(m.bytes, 'de')} fehlen in der Capture, wurden aber bestätigt`, d: (m) => `${m.gaps} Lücke(n) in ${m.conns} Verbindung(en) wurden vom Empfänger ohne Wiederholung bestätigt. Die Daten kamen an; die Capture hat sie nur nicht aufgezeichnet (Pufferüberlauf am Capture-Host oder SPAN-Port). Das ist kein Netzwerkverlust und wird nicht als solcher gezählt.`, n: () => 'Für eine sauberere Capture einen größeren Puffer (dumpcap -B), nur Header (Snaplen) oder einen Filter nutzen und auf eine schnelle Platte schreiben.' },
    'capture.offload_tso': { t: (m) => `${m.n} Segmente größer als die MSS (TSO/GRO)`, d: (m) => `Es gibt Segmente bis ${kb(m.max, 'de')}, obwohl die MSS ${m.mss} beträgt. Die Capture stammt von einem Host, dessen Netzwerkkarte Segmente zerlegt oder zusammenfasst (TCP Segmentation Offload / Generic Receive Offload). Auf der Leitung sind sie normal groß. Kein Fehler.`, n: () => 'Nichts zu tun. Um leitungsgroße Segmente zu sehen, an einem SPAN-Port mitschneiden oder Offload kurz abschalten (ethtool -K <if> tso off gro off).' },
    'capture.offload_csum': { t: (m) => `${m.n} Pakete mit ungültiger Prüfsumme (Checksum Offload)`, d: (m) => `${m.hosts === 1 ? 'Alle stammen von ' + m.host + ', höchstwahrscheinlich dem Capture-Host selbst' : 'Sie stammen von ' + m.hosts + ' Hosts'}. Die Netzwerkkarte trägt die Prüfsumme erst nach dem Messpunkt ein. Kein Fehler und nicht als solcher gezählt.`, n: () => 'Nichts zu tun. Nur relevant, wenn falsche Prüfsummen auch von entfernten Hosts kommen und gleichzeitig Wiederholungen auftreten.' },
    'capture.snaplen': { t: (m) => `${m.n} Pakete auf ${m.snaplen} Byte gekürzt`, d: () => 'Die Capture wurde mit kurzer Snapshot-Länge aufgenommen. Header und Längenfelder sind intakt, die TCP-Analyse funktioniert; Nutzdaten (z. B. TLS-SNI, DNS-Antworten) können fehlen. Gekürzte Pakete gelten nicht als beschädigt.', n: () => 'Für die TCP-Analyse ausreichend. Für Anwendungsdetails mit größerer Snaplen aufnehmen.' },
    'capture.no_handshake': { t: (m) => `${m.n} von ${m.of} TCP-Verbindungen begannen vor der Capture`, d: () => 'Ohne SYN sind Window-Scale-Faktor und Handshake-RTT dieser Verbindungen unbekannt. Fenstergrößen werden als Rohwerte gezeigt und nicht für Befunde genutzt.', n: () => 'Die Capture starten, bevor die Anwendung ihre Verbindungen öffnet.' },
